    if (done.has(number))
      continue;
    const goal = pyStr(or(get(post, "goal"), "")).toLowerCase();
    const account = pyStr(or(get(post, "account"), "")).toLowerCase();
    if (wanted && wanted !== goal && wanted !== account)
      continue;
